package com.xiaomiscalesync.xiaomi

import java.util.Base64
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Golden tests for [MiSigner] against `micloud_vectors.json`, which is
 * generated by a verbatim port of the reference client's helpers
 * (`token_extractor.py`: `signed_nonce`, `generate_enc_signature`,
 * `encrypt_rc4` / `decrypt_rc4`, `generate_enc_params`). Every value in
 * the fixture is pinned: the sign chain must reproduce it byte for byte.
 */
class MiSignerTest {

    private val vectors: List<MiCloudVector.Sign> =
        MiCloudVectors.load().filterIsInstance<MiCloudVector.Sign>()

    private fun fixture(name: String): MiCloudVector.Sign = vectors.first { it.name == name }

    @Test
    fun signedNonceMatchesGoldenSha256() {
        for (f in vectors) {
            assertEquals(f.signedNonce, MiSigner.signedNonce(f.ssecurity, f.nonce))
        }
        // Pinned value, independent of the fixture file (base64 SHA-256 of
        // base64-decoded ssecurity || base64-decoded nonce).
        assertEquals(
            "1KQS0QtX6elGRcx/c7P+h8NBs9g2WcdowXCQh/vI678=",
            fixture("mi_sign").signedNonce,
        )
    }

    @Test
    fun nonceIsTwelveBytesRandomPrefixPlusMinuteOfMillisBigEndian() {
        val f = fixture("mi_sign")
        val nonce = MiSigner.generateNonce(f.millis, f.nonceRandom)
        assertEquals(f.nonce, nonce)
        val decoded = Base64.getDecoder().decode(nonce)
        assertEquals(12, decoded.size)
        assertArrayEquals(f.nonceRandom, decoded.copyOfRange(0, 8))
        val minute = f.millis / 60_000
        assertArrayEquals(
            byteArrayOf(
                (minute shr 24).toByte(), (minute shr 16).toByte(),
                (minute shr 8).toByte(), minute.toByte(),
            ),
            decoded.copyOfRange(8, 12),
        )
    }

    @Test
    fun encParamsMatchGoldenFixtureExactly() {
        for (f in vectors) {
            val fields = MiSigner.encParams(
                url = f.url,
                method = f.method,
                signedNonceB64 = f.signedNonce,
                nonceB64 = f.nonce,
                params = f.params,
                ssecurityB64 = f.ssecurity,
                millis = f.millis,
            )
            assertEquals(f.encParams.keys.toList(), fields.keys.toList())
            for ((k, v) in f.encParams) {
                assertEquals("field '$k' of ${f.name}", v, fields[k])
            }
        }
    }

    @Test
    fun encParamsCarryThePinnedSignatureFields() {
        val f = fixture("mi_sign")
        val fields = MiSigner.encParams(
            f.url, f.method, f.signedNonce, f.nonce, f.params, f.ssecurity, f.millis,
        )
        // The brief's required fields, asserted individually and exactly.
        assertEquals(f.encParams["_nonce"], fields["_nonce"])
        assertEquals(f.nonce, fields["_nonce"])
        assertEquals(f.encParams["signature"], fields["signature"])
        assertEquals(f.encParams["rc4_hash__"], fields["rc4_hash__"])
        assertEquals(f.ssecurity, fields["ssecurity"])
        // The original data value is replaced by its base64 RC4 ciphertext.
        assertNotEquals(f.params["data"], fields["data"])
        assertTrue(fields["data"]!!.matches(Regex("[A-Za-z0-9+/=]+")))
    }

    @Test
    fun signatureIsSha1OverTheEncryptedValuesInThePinnedOrder() {
        val f = fixture("mi_sign")
        val fields = MiSigner.encParams(
            f.url, f.method, f.signedNonce, f.nonce, f.params, f.ssecurity, f.millis,
        )
        val signed = fields.filterKeys {
            it != "signature" && it != "ssecurity" && it != "_nonce"
        }
        assertEquals(
            f.encParams["signature"],
            MiSigner.encSignature(f.url, f.method, f.signedNonce, signed),
        )
        // rc4_hash__ covers the *plaintext* values, before encryption; on
        // the wire it carries that signature encrypted like every other value.
        assertEquals(
            MiSigner.decryptResponse(f.signedNonce, f.encParams["rc4_hash__"]!!),
            MiSigner.encSignature(f.url, f.method, f.signedNonce, f.params),
        )
    }

    @Test
    fun decryptResponseMatchesGoldenEncryptedBody() {
        val f = fixture("mi_sign")
        assertEquals(
            f.responsePlaintext,
            MiSigner.decryptResponse(f.signedNonce, f.responseCiphertext),
        )
    }

    @Test
    fun decryptResponseRoundTripsALocallyEncryptedBody() {
        val f = fixture("mi_sign")
        val body = """{"code":0,"result":{"device_info":[]}}"""
        val encrypted = MiSigner.encryptResponse(f.signedNonce, body)
        assertNotEquals(body, encrypted)
        assertEquals(body, MiSigner.decryptResponse(f.signedNonce, encrypted))
    }

    @Test
    fun cnRegionUrlIsSignedWithTheSamePathSegmentAsForeignRegions() {
        // url.split("com")[1].replace("/app/", "/") must yield the bare API
        // path for both `https://api.io.mi.com/...` (cn, no region prefix)
        // and `https://de.api.io.mi.com/...` — pinned by both fixtures'
        // golden signatures.
        val cn = fixture("mi_sign_cn")
        val de = fixture("mi_sign")
        assertEquals("/v2/home/home_device_list", pathSegment(cn.url))
        assertEquals("/v2/homeroom/gethome", pathSegment(de.url))
        assertNotEquals(cn.encParams["signature"], de.encParams["signature"])
    }

    private fun pathSegment(url: String): String = url.split("com")[1].replace("/app/", "/")
}
